import { TopologyModel } from "./TopologyModel.js";
function toType(type) {
    return type ?? "custom";
}
function toLabel(entity) {
    return entity.label ?? entity.title ?? entity.id;
}
function normalizeEntity(entity) {
    return {
        id: entity.id,
        type: toType(entity.type),
        title: entity.title ?? entity.label ?? entity.id,
        label: toLabel(entity),
        slug: entity.slug,
        language: entity.language,
        subtitle: entity.subtitle,
        summary: entity.summary,
        description: entity.description,
        body: entity.body,
        tags: Array.isArray(entity.tags) ? [...entity.tags] : [],
        q: typeof entity.q === "number" ? entity.q : undefined,
        r: typeof entity.r === "number" ? entity.r : undefined,
        metadata: entity.metadata ? { ...entity.metadata } : {},
    };
}
function normalizeRelationship(relationship) {
    return {
        from: relationship.from,
        to: relationship.to,
        kind: relationship.kind ?? "related",
        label: relationship.label,
        active: relationship.active,
        muted: relationship.muted,
    };
}
export class KnowledgeRepository {
    entityMap = new Map();
    relationshipRecords = [];
    issues = [];
    constructor(source) {
        for (const entity of source.entities) {
            if (this.entityMap.has(entity.id)) {
                this.issues.push({
                    type: "duplicate-entity",
                    message: "Duplicate entity id: " + entity.id,
                    entityId: entity.id,
                });
                continue;
            }
            this.entityMap.set(entity.id, normalizeEntity(entity));
        }
        for (const relationship of source.relationships ?? []) {
            const normalized = normalizeRelationship(relationship);
            const fromExists = this.entityMap.has(normalized.from);
            const toExists = this.entityMap.has(normalized.to);
            if (!fromExists || !toExists) {
                this.issues.push({
                    type: "broken-relationship",
                    message: "Broken relationship: " + normalized.from + " -> " + normalized.to,
                    relationship: normalized,
                });
                continue;
            }
            this.relationshipRecords.push(normalized);
        }
    }
    get issuesList() {
        return [...this.issues];
    }
    getEntity(id) {
        return this.entityMap.get(id) ?? null;
    }
    getByType(type) {
        return [...this.entityMap.values()].filter((entity) => entity.type === type);
    }
    getRelationships(id) {
        return this.relationshipRecords.filter((relationship) => relationship.from === id || relationship.to === id);
    }
    getNeighbors(id) {
        return this.getRelationships(id)
            .map((relationship) => {
            const neighborId = relationship.from === id ? relationship.to : relationship.from;
            return this.entityMap.get(neighborId) ?? null;
        })
            .filter((entity) => Boolean(entity));
    }
    getAllEntities() {
        return [...this.entityMap.values()];
    }
    getAllRelationships() {
        return [...this.relationshipRecords];
    }
    createWorld(options = {}) {
        const entities = this.getAllEntities()
            .filter((entity) => typeof entity.q === "number" && typeof entity.r === "number")
            .map((entity) => ({
            id: entity.id,
            label: entity.label,
            subtitle: entity.subtitle ?? entity.summary,
            q: entity.q,
            r: entity.r,
            type: entity.type === "page" || entity.type === "entry" ? "section" : "entity",
        }));
        const relationships = this.getAllRelationships().map((relationship) => ({
            from: relationship.from,
            to: relationship.to,
            kind: relationship.kind,
            active: relationship.active,
            muted: relationship.muted,
        }));
        return new TopologyModel({
            radius: options.radius ?? 40,
            columns: options.columns ?? 28,
            rows: options.rows ?? 18,
            originQ: options.originQ ?? 0,
            originR: options.originR ?? 0,
            entities,
            relationships,
        });
    }
}
